    ...rulesAfter,
  ];
  return {
    ATOMATON_FAKE_GH: FAKE_GH_IMPL,
    FAKE_GH_RESPONSES: JSON.stringify(rules),
    FAKE_GH_LOG: log,
    GH_TOKEN: "fake-gh-must-be-used",
    GITHUB_TOKEN: "fake-gh-must-be-used",
    GH_CONFIG_DIR: dir,
    ATOMATON_OPS_LOG: join(dir, "ops.log"),
  };
}

