+        "`content` for a whole-file rewrite.",
+    );
+  }
+  if (edit.new === undefined) {
+    throw new Error(`"${edit.path}": \`old\` was given without \`new\`. Give both, or \`content\` for a whole-file rewrite.`);
+  }
